<?php

declare(strict_types=1);

namespace Commerce\Core\I18n;

use Symfony\Component\HttpFoundation\RequestStack;
use Twig\Extension\AbstractExtension;
use Twig\TwigFilter;
use Twig\TwigFunction;

final class StorefrontUiTwigExtension extends AbstractExtension
{
    /** @var array<string,string>|null Lucide icon bodies generated by tools/build-lucide-icons.mjs */
    private static ?array $icons = null;

    public function __construct(
        private readonly StorefrontUiTranslator $translator,
        private readonly RequestStack $requests,
    ) {
    }

    public function getFunctions(): array
    {
        return [
            new TwigFunction('ui_text', $this->text(...), ['needs_context' => true]),
            new TwigFunction('ui_catalog_json', $this->catalogJson(...), ['needs_context' => true, 'is_safe' => ['html']]),
            new TwigFunction('ui_icon', $this->icon(...), ['is_safe' => ['html']]),
            new TwigFunction('ui_flag', LocaleFlag::img(...), ['is_safe' => ['html']]),
            new TwigFunction('status_badge', $this->statusBadge(...), ['needs_context' => true, 'is_safe' => ['html']]),
        ];
    }

    public function getFilters(): array
    {
        return [
            new TwigFilter('status_label', $this->statusLabel(...), ['needs_context' => true]),
        ];
    }

    public function icon(string $name, int $size = 20, string $class = ''): string
    {
        self::$icons ??= self::loadIcons();
        $body = str_starts_with($name, 'brand-')
            ? (self::loadBrandIcons()[$name] ?? '')
            : (self::$icons[$name] ?? '');
        if ($body === '' && preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D', $name) === 1) {
            // An icon an owner picked in the admin icon picker may come from the full Lucide library.
            self::$library ??= self::loadIconLibrary();
            $body = self::$library[$name] ?? '';
        }
        if ($body === '') {
            return '';
        }
        // Sizes snap to the design-token scale (xs 14, sm 16, md 20, lg 24, xl 32).
        $size = match (true) {
            $size <= 14 => 14,
            $size <= 16 => 16,
            $size <= 20 => 20,
            $size <= 24 => 24,
            default => 32,
        };
        $safeClass = preg_replace('/[^a-zA-Z0-9_:\- ]/', '', $class) ?: '';
        $classAttr = trim('ui-icon ' . $safeClass);
        $fill = str_ends_with($name, '-filled') ? 'currentColor' : 'none';

        return sprintf(
            '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="%s" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">%s</svg>',
            htmlspecialchars($classAttr, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'),
            $size,
            $size,
            $fill,
            $body,
        );
    }

    /** @var array<string,string>|null Official Tabler brand marks, loaded only when needed. */
    private static ?array $brandIcons = null;

    /** @return array<string,string> */
    private static function loadBrandIcons(): array
    {
        if (self::$brandIcons !== null) {
            return self::$brandIcons;
        }
        $file = dirname(__DIR__, 3) . '/resources/icons/tabler-brands.json';
        $data = is_file($file) ? json_decode((string) file_get_contents($file), true) : null;

        return self::$brandIcons = is_array($data['icons'] ?? null) ? $data['icons'] : [];
    }

    /** @var array<string,string>|null every Lucide icon, loaded only when an icon is missing from the curated set */
    private static ?array $library = null;

    /** @return array<string,string> */
    public static function loadIconLibrary(): array
    {
        $file = dirname(__DIR__, 3) . '/resources/icons/lucide-library.json';
        $data = is_file($file) ? json_decode((string) file_get_contents($file), true) : null;

        return array_merge(is_array($data['icons'] ?? null) ? $data['icons'] : [], self::loadBrandIcons());
    }

    /** @return array<string,string> */
    private static function loadIcons(): array
    {
        $file = dirname(__DIR__, 3) . '/resources/icons/lucide.json';
        $data = is_file($file) ? json_decode((string) file_get_contents($file), true) : null;

        return is_array($data['icons'] ?? null) ? $data['icons'] : [];
    }

    /** @param array<string,mixed> $context @param list<string> $prefixes */
    public function catalogJson(array $context, array $prefixes = []): string
    {
        $catalog = $this->catalog($context);
        if ($prefixes !== []) {
            $catalog = array_filter(
                $catalog,
                static function (string $key) use ($prefixes): bool {
                    foreach ($prefixes as $prefix) {
                        if (str_starts_with($key, (string) $prefix)) {
                            return true;
                        }
                    }
                    return false;
                },
                ARRAY_FILTER_USE_KEY,
            );
        }

        try {
            return json_encode($catalog, JSON_THROW_ON_ERROR | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
        } catch (\JsonException) {
            return '{}';
        }
    }

    /** @param array<string,mixed> $context @return array<string,string> */
    private function catalog(array $context): array
    {
        return $this->translator->catalogFor($this->uiLocale($context));
    }

    /** A coloured status chip for admin tables: the colour follows the status code, the text is its translation. */
    public function statusBadge(array $context, mixed $code, string $group = ''): string
    {
        $raw = trim((string) $code);
        $class = preg_replace('/[^a-z0-9_]/', '', strtolower($raw)) ?? '';

        return sprintf('<span class="admin-badge is-%s">%s</span>', $class !== '' ? $class : 'muted', htmlspecialchars($this->statusLabel($context, $raw, $group), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'));
    }

    /**
     * Human label for an order/payment/fulfilment status code: `status.<group>.<code>`, then `status.<code>`, then a
     * readable form of the code, so a status added by a module never shows an empty cell.
     *
     * @param array<string,mixed> $context
     */
    public function statusLabel(array $context, mixed $code, string $group = ''): string
    {
        $code = trim((string) $code);
        if ($code === '') {
            return '—';
        }
        if ($group !== '') {
            $grouped = $this->text($context, 'status.' . $group . '.' . $code);
            if ($grouped !== 'status.' . $group . '.' . $code) {
                return $grouped;
            }
        }
        $key = 'status.' . $code;
        $label = $this->text($context, $key);

        return $label !== $key ? $label : ucfirst(str_replace('_', ' ', $code));
    }

    public function text(array $context, string $key, array $replace = []): string
    {
        return $this->translator->translate($key, $this->uiLocale($context), $replace);
    }

    /**
     * The language interface texts are rendered in. An explicit `ui_locale` wins (an e-mail previewed in the admin).
     * In the back office it is always the administrator's interface language: there `locale` is the content language
     * being edited or a loop over languages and must not switch the labels. Elsewhere (storefront, e-mails sent to a
     * customer) the template's `locale`, else the request locale.
     *
     * @param array<string,mixed> $context
     */
    private function uiLocale(array $context): string
    {
        $explicit = is_string($context['ui_locale'] ?? null) ? trim($context['ui_locale']) : '';
        if ($explicit !== '') {
            return $explicit;
        }
        $request = $this->requests->getCurrentRequest();
        $admin = $request?->attributes->get(AdminInterfaceLocale::REQUEST_ATTRIBUTE);
        if (is_string($admin) && $admin !== '') {
            return $admin;
        }
        $template = is_string($context['locale'] ?? null) ? trim($context['locale']) : '';

        return $template !== '' ? $template : ($request?->getLocale() ?? 'uk-UA');
    }
}
